import cv2, numpy as np
a=np.load('source_pixels.npz')['rgb']
def warpf(im,flow):
 h,w=im.shape[:2]; xx,yy=np.meshgrid(np.arange(w,dtype=np.float32),np.arange(h,dtype=np.float32)); return cv2.remap(im,xx+flow[...,0],yy+flow[...,1],cv2.INTER_LINEAR,borderMode=cv2.BORDER_REFLECT)
def fb(i,j,pyr=0.5,levels=4,winsize=15):
 g1=cv2.cvtColor(a[i],cv2.COLOR_RGB2GRAY); g2=cv2.cvtColor(a[j],cv2.COLOR_RGB2GRAY)
 return cv2.calcOpticalFlowFarneback(g1,g2,None,pyr,levels,winsize,5,7,1.5,0)
def dis(i,j):
 g1=cv2.cvtColor(a[i],cv2.COLOR_RGB2GRAY); g2=cv2.cvtColor(a[j],cv2.COLOR_RGB2GRAY)
 d=cv2.DISOpticalFlow_create(cv2.DISOPTICAL_FLOW_PRESET_MEDIUM); d.setUseSpatialPropagation(True)
 return d.calc(g1,g2,None)
for name,fun in [('fb',fb),('dis',dis)]:
 f02=fun(0,2); f20=fun(2,0)
 w0=warpf(a[0].astype(np.float32),f02*.5)
 w2=warpf(a[2].astype(np.float32),f20*.5)
 mid=.5*(w0+w2)
 err=np.abs(mid-a[1].astype(float)).mean(2)
 for bbox in [(130,85,205,130),(0,0,256,144)]:
  x0,y0,x1,y1=bbox; e=err[y0:y1,x0:x1]
  print(name,bbox,'mae',e.mean(),'p90',np.percentile(e,90),'max',e.max())
 cv2.imwrite('.tmp/mid_'+name+'.png',cv2.cvtColor(np.clip(mid,0,255).astype('uint8'),cv2.COLOR_RGB2BGR))
