import numpy as np, cv2
a=np.load('source_pixels.npz')['rgb'].astype(np.float32)
# Try sprite trajectory by extracting car foreground from source frames and moving it at 0.6 speed on fixed bg.
# Foreground source frame f already includes car at pos. To make slowed output at t, choose source f=t*0.6 and adjust sprite to source position at f*.6? Use source frames natural.
# Need interpolate source with slow time; use linear interpolation of actual frames with optical flow. For fractional source index s=i*.6.
# DIS forward backward blend with warps scaled to fractional t. Evaluate visually/proxy.
def flow(i,j):
 d=cv2.DISOpticalFlow_create(cv2.DISOPTICAL_FLOW_PRESET_MEDIUM);d.setUseSpatialPropagation(True)
 return d.calc(cv2.cvtColor(a[i].astype('uint8'),cv2.COLOR_RGB2GRAY),cv2.cvtColor(a[j].astype('uint8'),cv2.COLOR_RGB2GRAY),None)
def warp(im,flow):
 h,w=im.shape[:2];xx,yy=np.meshgrid(np.arange(w,dtype=np.float32),np.arange(h,dtype=np.float32));return cv2.remap(im,xx+flow[...,0],yy+flow[...,1],cv2.INTER_LINEAR,borderMode=cv2.BORDER_REFLECT)
def interp(i,j,t):
 fi=flow(i,j); fj=flow(j,i)
 w0=warp(a[i],fi*t);w1=warp(a[j],fj*(1-t))
 # weight visibility via forward/backward consistency? basic blend
 return (w0*(1-t)+w1*t)
# create slowed 96 frames at s=i*.6 capped at 20 (scene static after)
out=[]
for k in range(96):
 s=k*.6
 if s>=20: out.append(a[min(95,int(round(s)))])
 else:
  i=int(np.floor(s)); f=s-i
  if f<1e-5: out.append(a[i])
  else: out.append(interp(i,i+1,f))
out=np.clip(np.stack(out),0,255).astype('uint8')
# save preview sheet
from PIL import Image,ImageDraw
sel=[0,5,10,15,20,25,30,33,35,40,60,95]
sheet=Image.new('RGB',(256*4,(144+20)*3),(20,20,20));dr=ImageDraw.Draw(sheet)
for j,i in enumerate(sel):
 x=(j%4)*256;y=(j//4)*164;dr.text((x+3,y+2),str(i),fill='white');sheet.paste(Image.fromarray(out[i]),(x,y+20))
sheet.save('.tmp/slow_dis_sheet.png')
# save frames
for i in [0,5,10,15,20,25,30,33,35]: cv2.imwrite(f'.tmp/slow_{i:02d}.png',cv2.cvtColor(out[i],cv2.COLOR_RGB2BGR))
print('done',out.shape)
PY"
